/* Static design preview. All state and actions are local to this browser. */
(() => {
  'use strict';
  const $ = (q, root=document) => root.querySelector(q);
  const chars = window.CONNECTA_CHARACTERS;
  const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function read(key, fallback) { try { return JSON.parse(localStorage.getItem('connecta-preview-'+key)) ?? fallback; } catch { return fallback; } }
  function save(key, value) { try { localStorage.setItem('connecta-preview-'+key, JSON.stringify(value)); } catch { /* Preview also works with storage disabled. */ } }
  const state = {
    route:'home', avatar:read('avatar',7), name:read('name','Nont'), role:'Visitor', panel:null,
    project:0, department:'All projects', eventFilter:'All events', projectSearch:'', eventSearch:'',
    mic:false, cam:false, paused:read('paused',false), zoom:1, direction:0, avatarWalking:false,
    scores:[0,0,0,0], submitted:read('scores',{}), saved:read('saved',[]), tour:0,
    modules:read('modules',{booths:true,meetings:true,qa:true,sponsors:false}),
    messages:[], registered:read('registered',false), profile:read('profile',{}),
    booth:read('booth',{title:'Sign-language recognition on edge devices',abstract:'Making everyday conversations more accessible. Our on-device model recognises hand gestures in real time, with no internet connection required.',status:'Available',link:'https://example.com/sign-language'}),
    eventDraft:read('event-draft',{}), scheduleSaved:read('schedule',[])
  };
  if(!Number.isInteger(state.avatar)||!chars[state.avatar]) state.avatar=7;
  const paths = {
    arrow:'M5 12h14m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',back:'M19 12H5m6-6-6 6 6 6',down:'m6 9 6 6 6-6',close:'m6 6 12 12M6 18 18 6',
    search:'m21 21-4.4-4.4M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
    mic:'M12 15a3 3 0 0 0 3-3V5a3 3 0 0 0-6 0v7a3 3 0 0 0 3 3ZM5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8',
    micOff:'m2 2 20 20M9 9v3a3 3 0 0 0 5 2m1-6V5a3 3 0 0 0-5.4-1.8M5 10v2a7 7 0 0 0 12 5M19 10v2m-7 7v3m-4 0h8',
    video:'m16 8 6-4v16l-6-4M3 5h11a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2Z',
    videoOff:'m2 2 20 20M16 8l6-4v16l-6-4M6 5h8a2 2 0 0 1 2 2v5M16 17a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V7a2 2 0 0 1 1-1.7',
    chat:'M21 11a8 8 0 0 1-8 8H7l-5 3V6a3 3 0 0 1 3-3h8a8 8 0 0 1 8 8ZM7 8h9M7 12h6',
    users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8m6 10v-2a4 4 0 0 0-3-3.9M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
    calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Z',
    clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
    grid:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7Z',
    map:'m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3V6Zm6-3v15m6-12v15',
    pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
    globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM2 12h20M12 2c5 5 5 15 0 20-5-5-5-15 0-20',
    star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z',
    check:'m5 12 4 4L19 6',checkCircle:'m8 12 3 3 5-6M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
    mail:'m3 5 9 7 9-7M4 4h16a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Z',
    bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',
    settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z',
    chart:'M4 3v18h17M9 17v-5m5 5V7m5 10V4',
    download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',
    upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',
    file:'M14 2H5a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9l-7-7Zm0 0v7h7M7 13h10M7 17h6',
    book:'M12 6c-3-3-7-3-10-1v15c3-2 7-2 10 1 3-3 7-3 10-1V5c-3-2-7-2-10 1Zm0 0v15',
    save:'M5 3h12l4 4v14H3V3h2Zm2 0v6h10V3M7 21v-8h10v8',
    bookmark:'M5 3h14v19l-7-4-7 4V3Z',
    plus:'M12 5v14M5 12h14',minus:'M5 12h14',
    play:'m8 4 13 8-13 8V4Z',pause:'M7 4v16M17 4v16',
    leave:'M9 3H3v18h6m5-14 5 5-5 5m-6-5h13',
    wave:'M7 12 4 7a2 2 0 0 1 3-2l4 6-3-7a2 2 0 0 1 3-1l3 7-1-7a2 2 0 0 1 3 0l1 9 1-3a2 2 0 0 1 3 1l-1 6c-2 8-12 7-15 1l-2-4a2 2 0 0 1 3-2l3 3',
    shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4Zm-4 10 3 3 5-6',
    link:'M10 13a5 5 0 0 0 7 0l4-4a5 5 0 0 0-7-7l-2 2m2 7a5 5 0 0 0-7 0l-4 4a5 5 0 0 0 7 7l2-2',
    headphones:'M3 14v-3a9 9 0 0 1 18 0v3M3 13h4v8H3V13Zm14 0h4v8h-4v-8Z',
    info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
    trophy:'M8 3h8v7a4 4 0 0 1-8 0V3ZM8 5H3v3a4 4 0 0 0 5 4m8-7h5v3a4 4 0 0 1-5 4m-4 2v6m-4 1h8',
    leaf:'M20 3C10 1 3 6 4 13s11 9 15 1c2-4 1-11 1-11ZM4 20 15 9',
    hand:'M8 13V5a2 2 0 0 1 4 0v6-8a2 2 0 0 1 4 0v8-5a2 2 0 0 1 4 0v10c0 9-12 8-15 3l-3-5a2 2 0 0 1 3-2l3 3',
    monitor:'M3 3h18v14H3V3Zm9 14v4m-5 0h10',
    more:'M5 12h.01M12 12h.01M19 12h.01',
    user:'M20 21v-2a6 6 0 0 0-6-6h-4a6 6 0 0 0-6 6v2M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0'
  };
  const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
  const brand = () => `<a class="brand" href="#home" aria-label="Connecta home"><span class="brand-mark" aria-hidden="true"></span><span translate="no">Connecta</span></a>`;
  const btn = (text,href,cls='',i='') => `<a class="btn ${cls}" href="${href}">${i?icon(i):''}${text}</a>`;
  const action = (text,name,cls='',i='',extra='') => `<button type="button" class="btn ${cls}" data-action="${name}" ${extra}>${i?icon(i):''}${text}</button>`;
  const iconButton = (name,label,extra='') => `<button type="button" class="icon-btn" aria-label="${label}" title="${label}" ${extra}>${icon(name)}</button>`;
  const pill = (text,cls='') => `<span class="pill ${cls}">${text}</span>`;
  const status = (text='Live now',count='') => pill(`<span class="dot"></span>${text}${count?' · '+count:''}`,'live');
  const initials = name => escape(name.split(' ').map(n=>n[0]).slice(0,2).join(''));
  const actor = (index,options={}) => {
    const c=chars[index%chars.length];
    return `<div class="sprite-actor ${!options.walk?'breathing':''}" data-character="${index%chars.length}" data-direction="${options.direction||0}" data-walking="${!!options.walk}" ${options.ambient?'data-ambient="true"':''} ${options.npc?'data-npc="'+index+'"':''} ${options.player?'data-player="true"':''} style="${options.style||''}" ${options.name?'role="img" aria-label="'+escape(options.name)+'"':'aria-hidden="true"'}><div class="sprite-body" style="background-image:url('${c.walk}')"></div>${options.name?`<span class="name-tag ${options.player?'you':''}">${escape(options.name)}</span>`:''}</div>`;
  };
  const projects=[
    {code:'A01',title:'Mapping urban heat with open satellite data',short:'Aurora',dept:'Engineering',tag:'Climate & cities',live:true,people:14,abstract:'Turning open satellite imagery into practical maps of urban heat. Explore how greener streets and better urban planning can make our cities more comfortable.',color:'blue',presenter:'Mika'},
    {code:'A07',title:'Sign-language recognition on edge devices',short:'Pixel Path',dept:'Computing',tag:'AI & accessibility',live:true,people:22,abstract:'Making everyday conversations more accessible. Our on-device model recognises hand gestures in real time, with no internet connection required.',color:'purple',presenter:'Prae'},
    {code:'B03',title:'A smarter soil-moisture network for campus gardens',short:'GreenLoop',dept:'Engineering',tag:'Environment & IoT',live:true,people:9,abstract:'Small sensors, healthier gardens. This low-cost sensor network helps campus gardeners use less water and gives students a live view of soil health.',color:'green',presenter:'Phum'},
    {code:'B09',title:'A modular bike-share dock from recycled aluminium',short:'Re:Cycle',dept:'Design',tag:'Circular design',live:false,people:0,abstract:'A repairable bike dock made from reclaimed aluminium, designed to make short campus trips easier and reduce material waste.',color:'orange',presenter:'Ren'},
    {code:'C02',title:'Adaptive prosthetic grip with tactile feedback',short:'Touchpoint',dept:'Health',tag:'Assistive technology',live:false,people:0,abstract:'A lightweight prosthetic hand that gives the wearer useful feedback when holding everyday objects. Meet the team and explore the prototype.',color:'purple',presenter:'Dr. Pim'},
    {code:'C05',title:'Speech-to-text tutoring for first-generation students',short:'Open Notes',dept:'Computing',tag:'Education & HCI',live:true,people:11,abstract:'Accessible lecture notes and real-time captions, co-designed with students to make learning easier to follow.',color:'blue',presenter:'Fah'}
  ];
  const pages=[['home','Landing','The first hello','globe'],['events','Discover events','Find a showcase','search'],['signup','Create account','Registration & roles','user'],['signin','Sign in','Return to Connecta','leave'],['event','Event page','Projects & event details','grid'],['avatar','Character lobby','14 characters & devices','users'],['hall','Visitor hall','Map, NPCs & proximity','map'],['judge','Judge hall','Scoring & private notes','trophy'],['schedule','Agenda','Sessions & speakers','calendar'],['presenter','My booth','Presenter workspace','monitor'],['organizer','Organizer','Attendees & event modules','settings'],['create-event','Create event','Set up a showcase','plus'],['analytics','Event report','Attendance & judging','chart'],['profile','My profile','Details & contacts','user']];
  const routeLink = (id,label) => `<a href="#${id}" class="${state.route===id?'active':''}">${label}</a>`;
  function header(home=false) {
    return `<header class="${home?'home-nav':'nav-wrap'}"><nav class="nav container" aria-label="Main navigation">${brand()}<div class="nav-links">${routeLink('events','Events')}${routeLink('event','Showcase')}${routeLink('schedule','Agenda')}${routeLink('organizer','For organizers')}</div><div class="nav-actions">${home?`${btn('Sign in','#signin','ghost')}${btn('Host a showcase','#create-event')}`:`${iconButton('bell','Notifications','data-action="notifications"')}<span class="divider"></span><a class="avatar-pill" href="#profile" aria-label="Open your profile"><span class="avatar-dot">${initials(state.name)}</span>${icon('down')}</a>`}</div></nav></header>`;
  }
  const search = (id,label,placeholder) => `<div class="search">${icon('search')}<input id="${id}" class="search-input" type="search" aria-label="${label}" placeholder="${placeholder}" autocomplete="off"></div>`;
  const avatarStack = () => `<div class="avatar-stack" aria-hidden="true">${[8,9,12].map(i=>`<span class="mini-face"><img src="assets/characters/${chars[i].id}-portrait.png" width="29" height="29" alt=""></span>`).join('')}</div>`;
  function poster(project,large=false) {
    const p=project, colors={blue:['#e8efff','#1d5cf5','#97b3fc'],purple:['#ede5fb','#7651b1','#c4afe9'],green:['#e4f2df','#36865e','#a7ce98'],orange:['#fff0df','#c56f27','#f1c390']},[bg,ink,soft]=colors[p.color];
    const symbols = p.color==='green'?'<path d="M260 55c-40-6-60 12-49 35 15 24 49 3 49-35M211 106l35-34" fill="none" stroke="'+ink+'" stroke-width="7"/>':p.color==='purple'?'<path d="M220 53v38m10-45v42m11-36v38m12-27v33c0 26-28 31-39 12l-14-20" fill="none" stroke="'+ink+'" stroke-width="8" stroke-linecap="round"/>':'<circle cx="238" cy="79" r="31" fill="none" stroke="'+ink+'" stroke-width="8"/><path d="M232 60v20l18 10" fill="none" stroke="'+ink+'" stroke-width="5"/>';
    return `<svg viewBox="0 0 320 200" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${escape(p.short)} project poster"><rect width="320" height="200" fill="${bg}"/><circle cx="291" cy="48" r="76" fill="${soft}" opacity=".45"/><circle cx="290" cy="48" r="55" fill="none" stroke="${ink}" stroke-opacity=".12" stroke-width="1"/><text x="24" y="35" fill="${ink}" font-size="10" font-family="sans-serif" font-weight="700">${p.code} / SENIOR DESIGN SHOWCASE</text><text x="24" y="78" fill="#0f1a3a" font-size="29" font-family="sans-serif" font-weight="800">${escape(p.short)}</text><text x="24" y="104" fill="${ink}" font-size="10" font-family="sans-serif">${escape(p.tag)}</text><path d="M24 133h113m-113 11h94m-94 11h107" stroke="${ink}" stroke-width="3" opacity=".3"/><rect x="24" y="175" width="36" height="3" rx="1.5" fill="${ink}"/><text x="68" y="179" fill="${ink}" font-size="8" font-family="sans-serif">Explore the project. Meet the people.</text>${symbols}</svg>`;
  }
  function eventCard(index=0) {
    const events=[{title:'Senior Design Showcase 2026',date:'Today · 10:00–16:00',host:'Faculty of Engineering',booths:42,live:true,art:'map'},{title:'Ideas for a greener tomorrow',date:'23 Oct · 10:00–15:00',host:'Sustainability & Design Lab',booths:24,live:false,art:'purple'},{title:'Capstone Demo Day',date:'30 Oct · 09:00–16:00',host:'School of Information Technology',booths:30,live:false,art:'orange'}];
    const e=events[index];
    return `<article class="event-card"><a href="#event" class="event-image" aria-label="View ${e.title}">${e.art==='map'?'<img src="assets/maps/exhibition/minimap.png" width="1536" height="855" alt="A top-down exhibition hall with a stage, booths and meeting area" loading="lazy">':`<div class="event-art ${e.art}"><div class="art-orbit"></div><strong>${index===1?'Good ideas.<br>Greener futures.':'Made here.<br>Shared everywhere.'}</strong><span>${index===1?'Sustainability showcase 2026':'Capstone demo day 2026'}</span>${actor(index===1?9:7,{walk:true})}</div>`}${e.live?status('Live now'):pill('Upcoming','light')}</a><div class="event-card-body"><span class="small-text muted">${e.date}</span><h3><a href="#event">${e.title}</a></h3><p>${e.host}</p><div class="event-card-foot"><span class="flex">${icon('grid')}${e.booths} booths${e.live?' · 211 online':''}</span><a href="#event" class="text-link">${e.live?'View event':'Register'} ${icon('arrow')}</a></div></div></article>`;
  }
  function home() {
    return `${header(true)}<main id="main" class="page home"><div class="container"><section class="hero"><div class="hero-copy reveal"><span class="pill light"><span class="dot live-dot"></span>3 showcases live right now</span><h1>Demo day,<br>without the venue.</h1><p>Walk into a world of student ideas. Meet the people behind the projects, start a conversation, and see what happens next.</p><div class="hero-cta">${btn('Explore events','#events','','arrow')}${action('Watch the tour','tour','secondary','play')}</div><div class="social-proof">${avatarStack()}<span>A space for curious minds to meet.</span></div></div><div class="hero-art reveal" style="animation-delay:100ms"><div class="browser-card"><div class="browser-top"><div class="traffic-lights"><i></i><i></i><i></i></div><span class="browser-url">connecta.space / showcase</span>${icon('globe')}</div><div class="hero-world lobby-hero"><img src="assets/images/lobby.png" width="1103" height="1426" fetchpriority="high" alt="Students and lecturers meeting in a bright university lobby">${actor(7,{ambient:true,walk:true,style:'left:55%;top:64%;',name:'You'})}${actor(9,{ambient:true,walk:true,style:'left:72%;top:48%;'})}${actor(12,{ambient:true,style:'left:37%;top:56%;'})}<div class="mini-hud">${['mic','video','chat','wave','map'].map(i=>icon(i)).join('')}</div></div></div><div class="connection-note">${icon('checkCircle')}A new connection is one hello away.</div><div class="booth-float"><div class="flex between"><span class="booth-code">Booth A07</span>${status('Presenting')}</div><h3>Sign-language recognition<br>on edge devices</h3><div class="flex">${avatarStack()}<span class="small-text muted">22 people listening</span></div></div></div></section><section class="roles-strip" aria-label="Who Connecta is for">${[['users','Come curious. Leave connected.','Explore projects and talk to their creators.'],['monitor','Give your ideas a little room.','Present, share your work, and get feedback.'],['trophy','Every perspective counts.','Judge projects from the same shared hall.']].map(([i,h,p])=>`<div class="role-item"><span class="role-icon">${icon(i)}</span><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</section><section class="home-section scroll-reveal"><div class="section-heading"><div><h2>Happening on Connecta</h2><p>Find your next conversation.</p></div><a class="text-link" href="#events">All events ${icon('arrow')}</a></div><div class="event-grid">${[0,1,2].map(eventCard).join('')}</div></section><section class="home-section scroll-reveal"><div class="section-heading"><div><h2>A few steps. A lot to discover.</h2><p>Getting together should be the easy part.</p></div></div><div class="steps-grid">${[['Find your people','Pick an event that sparks your curiosity. Register once, and you are on the list.'],['Make yourself at home','Choose your character, check your devices, and step into the hall.'],['Walk up. Say hello.','Browse a booth, ask a question, or settle into a conversation.']].map(([h,p],i)=>`<article><div class="step-image"><img src="assets/images/step-${i+1}.png" alt="${h}" width="600" height="400" loading="lazy"></div><div class="step-title"><span class="step-num">${i+1}</span><h3>${h}</h3></div><p>${p}</p></article>`).join('')}</div></section><section class="host-banner scroll-reveal"><div><h2>Running a demo day this term?</h2><p>Bring the projects. We will make room for the conversations.</p></div>${btn('Host a showcase','#create-event','','plus')}</section><footer class="footer">${brand()}<a href="#events">Events</a><a href="#organizer">For organizers</a><a href="#profile">Your profile</a><span>Made for meeting minds.</span></footer></div></main>`;
  }
  function events() {
    return `${header()}<main id="main" class="page container page-content"><div class="page-title"><h1>Find your next conversation.</h1><p>Student projects, fresh perspectives, and people worth meeting.</p></div><div class="project-toolbar"><div class="chips">${['All events','Live now','Upcoming','Archive'].map(f=>`<button class="chip ${state.eventFilter===f?'active':''}" data-action="event-filter" data-value="${f}" aria-pressed="${state.eventFilter===f}">${f}</button>`).join('')}</div>${search('event-search','Search events','Search events…')}</div><div id="event-results" class="event-grid">${eventResults()}</div><div class="event-summary-strip"><div><h3>Your ideas deserve an audience.</h3><p>Planning a showcase for your department? Start with a ready-made space.</p></div>${btn('Create an event','#create-event','secondary small','plus')}</div></main>`;
  }
  function eventResults() {
    let ids=state.eventFilter==='Live now'?[0]:state.eventFilter==='Upcoming'?[1,2]:state.eventFilter==='Archive'?[]:[0,1,2];
    ids=ids.filter(i=>['Senior Design Showcase 2026','Ideas for a greener tomorrow','Capstone Demo Day'][i].toLowerCase().includes(state.eventSearch.toLowerCase()));
    return ids.length?ids.map(eventCard).join(''):empty(state.eventFilter==='Archive'?'No past events yet':'No events found','Try another search or browse all upcoming showcases.');
  }
  function empty(title,text) { return `<div class="empty-state">${icon('search')}<h3>${title}</h3><p class="body-text">${text}</p></div>`; }
  function auth(signin=false) {
    return `<main id="main" class="page auth-layout"><section class="auth-visual">${brand()}<div class="auth-picture"><img src="assets/images/lobby.png" width="1104" height="1424" alt="Students and lecturers talking in a sunlit university lobby"></div><div><span class="pill light">${signin?'Welcome back':'Your next connection starts here'}</span><h2 style="margin-top:16px">${signin?'Good to see you.<br>There is a lot to catch up on.':"You're one step closer to Senior Design Showcase 2026."}</h2><p style="margin-top:14px">Fri 16 Oct · 10:00–16:00 · 42 booths</p></div><div class="auth-quote">${avatarStack()}<span>A little closer, wherever you are.</span></div></section><section class="auth-form-wrap"><div class="auth-form"><a href="#home" class="text-link" style="margin-bottom:26px">${icon('back')} Back to Connecta</a><h1>${signin?'Welcome back.':'Create your account'}</h1><p>${signin?'Your people and projects are waiting.':'One account. A whole world of ideas.'}</p>${!signin?`<div class="role-segment" aria-label="Preview event role">${['Visitor','Presenter','Judge','Staff'].map(r=>`<button type="button" class="${state.role===r?'active':''}" data-action="role" data-value="${r}" aria-pressed="${state.role===r}">${r}</button>`).join('')}</div><p class="field-note" id="role-note" style="margin:-9px 0 20px">${state.role==='Visitor'?'Explore the showcase and meet the creators.':'Event roles are granted by the organizer. This selector previews the role only.'}</p>`:''}<form id="${signin?'signin':'signup'}-form" class="auth-fields">${!signin?`<label class="field" for="fullname">Full name<input id="fullname" name="fullname" autocomplete="name" placeholder="e.g. Nont Chaiyaporn…" required maxlength="80"></label>`:''}<label class="field" for="email">University email<input id="email" name="email" type="email" autocomplete="email" spellcheck="false" placeholder="you@university.ac.th…" required></label><label class="field" for="password">Password<input id="password" name="password" type="password" autocomplete="${signin?'current-password':'new-password'}" placeholder="At least 8 characters…" minlength="8" required></label>${!signin?'<label class="consent"><input type="checkbox" name="terms" required><span>I agree to the terms and privacy notice. Event registration is a separate step.</span></label>':''}<p id="auth-error" class="form-error" role="alert"></p><button class="btn wide" type="submit">${signin?'Sign in':'Create account'} ${icon('arrow')}</button></form><div class="divider-text">or continue with</div>${action('Continue with university SSO','sso','secondary wide','shield')}<div class="auth-bottom">${signin?'New to Connecta? <a href="#signup" class="text-link">Create an account</a>':'Already have an account? <a href="#signin" class="text-link">Sign in</a>'}</div><p class="field-note" style="margin-top:24px;text-align:center">Interactive preview · use any sample details</p></div></section></main>`;
  }
  function eventPage() {
    return `${header()}<main id="main" class="page container page-content"><div class="breadcrumb"><a href="#events">Events</a>${icon('chevron')}<span>Senior Design Showcase 2026</span></div><section class="event-hero"><div class="event-hero-copy"><div class="flex">${status('Live now','211 in hall')}${pill('Faculty of Engineering','blue')}</div><h1>Senior Design<br>Showcase 2026</h1><p>A year of making, questioning, and figuring things out. Meet the students turning their ideas into something real.</p><div class="flex" style="margin-top:23px">${avatarStack()}<span class="small-text muted">42 projects. Plenty to talk about.</span></div></div><div class="event-meta">${[['calendar','Friday, 16 October 2026'],['clock','10:00–16:00 ICT'],['grid','42 booths · 31 presenting'],['globe','Online · Connecta Exhibition Hall']].map(([i,t])=>`<div class="event-meta-row">${icon(i)}${t}</div>`).join('')}${btn('Enter the hall','#avatar','','arrow')}<span class="registered">${icon('check')}${state.registered?"You're registered":'Free for everyone with an account'}</span></div></section><nav class="tabs" aria-label="Event navigation"><a class="tab active" href="#event">Projects</a><a class="tab" href="#schedule">Agenda</a><button class="tab" data-action="event-about">About this event</button><a class="tab" href="#profile">My connections</a></nav><div class="section-heading"><div><h2>Big ideas, meet curious minds.</h2><p>Walk up to a booth and hear the story behind the project.</p></div><span class="small-text muted" id="project-count">6 featured projects</span></div><div class="project-toolbar"><div class="chips">${['All projects','Live now','Engineering','Computing','Health','Design'].map(f=>`<button type="button" class="chip ${state.department===f?'active':''}" data-action="project-filter" data-value="${f}" aria-pressed="${state.department===f}">${f}</button>`).join('')}</div>${search('project-search','Search projects','Search projects…')}</div><div id="project-results" class="project-grid">${projectResults()}</div><section class="event-summary-strip"><div><h3>A conversation is happening on the main stage.</h3><p>Designing for everyday accessibility with Dr. Arun Wattanapong</p></div>${btn('See the agenda','#schedule','secondary small','calendar')}</section></main>`;
  }
  function projectResults() {
    const filtered=projects.map((p,i)=>({...p,i})).filter(p=>(state.department==='All projects'||(state.department==='Live now'?p.live:p.dept===state.department))&&`${p.title} ${p.code} ${p.dept}`.toLowerCase().includes(state.projectSearch.toLowerCase()));
    return filtered.length?filtered.map(p=>`<button class="project-card" data-action="project" data-index="${p.i}"><div class="card-top"><span class="booth-code">${p.code}</span>${p.live?status('Presenting',p.people+' here'):pill('Back at 14:30')}</div><h3>${p.title}</h3><p>${p.dept} <span style="color:var(--border)">/</span> ${p.tag}</p></button>`).join(''):empty('No projects found','Try a different topic or choose another department.');
  }
  function lobby() {
    return `${header()}<main id="main" class="page container narrow page-content"><div class="breadcrumb"><a href="#event">Senior Design Showcase 2026</a>${icon('chevron')}<span>Before you enter</span></div><div class="page-title"><h1>Make yourself at home.</h1><p>Choose a familiar face and check your setup. You can change these anytime.</p></div><div class="lobby-layout"><section><div class="avatar-stage"><div class="avatar-stage-caption">${pill('Your character','blue')}</div><div id="selected-avatar">${actor(state.avatar,{name:state.name,walk:state.avatarWalking,direction:state.direction})}</div><div class="avatar-controls">${iconButton('back','Turn character left','data-action="avatar-turn" data-direction="2"')}${iconButton('user','Face forward','data-action="avatar-turn" data-direction="0"')}${iconButton('arrow','Turn character right','data-action="avatar-turn" data-direction="3"')}${iconButton('play','Preview walking','data-action="avatar-walk"')}</div></div><div class="flex between" style="margin-top:21px"><h3 style="font-size:.875rem">Pick your character</h3><span class="small-text muted">14 to choose from</span></div><div class="character-grid">${chars.map((c,i)=>`<button type="button" class="character-option ${state.avatar===i?'active':''}" data-action="avatar" data-index="${i}" aria-label="Choose ${escape(c.name)}" aria-pressed="${state.avatar===i}"><img src="assets/characters/${c.id}-portrait.png" width="80" height="80" alt=""><span>${c.name}</span></button>`).join('')}</div><p class="field-note" style="margin-top:12px">Use the arrows to turn. Press play to preview the walk cycle.</p></section><section class="surface lobby-settings"><h2>Ready when you are.</h2><label class="field" for="display-name">Your display name<input id="display-name" name="display-name" autocomplete="nickname" value="${escape(state.name)}" maxlength="30" required></label><div class="camera-preview" style="margin-top:20px"><span>${icon(state.cam?'video':'videoOff')}</span><span>${state.cam?'Camera preview placeholder':'Your camera is off'}</span></div><label class="device-row"><span class="flex">${icon('mic')}Microphone</span><input class="switch" type="checkbox" data-setting="mic" ${state.mic?'checked':''} aria-label="Microphone preview state"></label><label class="device-row"><span class="flex">${icon('video')}Camera</span><input class="switch" type="checkbox" data-setting="cam" ${state.cam?'checked':''} aria-label="Camera preview state"></label><p class="field-note" style="margin:13px 0 18px">Device controls are a UI preview. No hardware is accessed.</p><div class="info-note">${icon('headphones')}<span>In the hall, walk closer to start a conversation. Headphones make it easier to hear each other.</span></div>${action("Let's go in",'enter-hall','wide','arrow','style="margin-top:23px"')}</section></div></main>`;
  }
  function hall(judge=false) {
    const spots=[['booth',0,9,8,20,25],['booth',1,9,36,20,25],['booth',2,9,62,20,23],['stage',0,35,2,29,28],['meeting',0,70,6,25,28]];
    const spawn=[[36,37],[63,53],[74,72],[45,73],[64,74],[33,63],[58,68],[39,50],[74,48],[66,42],[60,38],[36,70],[70,59],[49,68]];
    return `<main id="main" class="page hall-page" aria-label="${judge?'Judge':'Visitor'} exhibition hall"><div class="hall-world-container"><div class="hall-world" id="hall-world" style="--zoom:${state.zoom}"><img class="map-backdrop" src="assets/maps/exhibition/minimap.png" width="1536" height="855" alt="Exhibition map. Three booths on the left, main stage at the top, meeting room at the top right, and seating in the centre."><div class="proximity-ring" id="proximity-ring" style="left:53%;top:76%"></div>${spots.map(([a,i,x,y,w,h])=>`<button class="hotspot" style="left:${x}%;top:${y}%;width:${w}%;height:${h}%" data-action="${a==='booth'?'hall-booth':a}" data-index="${i}" aria-label="${a==='booth'?'Visit '+projects[i].short+' booth':a==='stage'?'Join the main stage':'Enter the meeting room'}"><span class="hotspot-label">${a==='booth'?'View '+projects[i].short:a==='stage'?'Join the stage':'Meeting room'}</span></button>`).join('')}${chars.map((c,i)=>actor(i,{npc:true,walk:i%3!==0,name:c.name,style:`left:${spawn[i][0]}%;top:${spawn[i][1]}%;`})).join('')}${actor(state.avatar,{player:true,name:state.name+' (you)',style:'left:51%;top:71%;'})}</div></div><div class="hall-title">${brand()}<span class="divider"></span><div class="hall-title-event"><strong>Senior Design Showcase 2026</strong><small><span class="dot" style="color:var(--green)"></span> Exhibition Hall · 211 online</small></div></div>${judge?`<div class="judge-banner">${icon('trophy')}<strong>Judge mode</strong><span id="judge-progress">${Object.keys(state.submitted).length} of 12 scored</span><span>· closes in 1h 24m</span></div>`:''}<div class="hall-top-right">${pill('<span class="dot" style="color:var(--green)"></span>Connected','green')}${iconButton('info','How to move','data-action="hall-help"')}</div><nav class="hall-left-tools" aria-label="Hall tools">${iconButton('users','People in this hall','data-action="panel" data-panel="people"')}${iconButton('calendar','Event agenda','data-action="panel" data-panel="agenda"')}${iconButton('bookmark','Saved projects','data-action="panel" data-panel="saved"')}${iconButton('settings','Hall settings','data-action="panel" data-panel="settings"')}</nav><div id="video-area"></div><div id="hall-panel-container">${judge?rubricPanel():''}</div><div class="hall-hint">Move with <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> or arrow keys · Click a booth to explore</div><div class="hall-toolbar" aria-label="Hall controls">${tool('mic',state.mic?'Mic on':'Mic off',state.mic,state.mic?'mic':'micOff')}${tool('cam',state.cam?'Camera on':'Camera off',state.cam,state.cam?'video':'videoOff')}${tool('chat','Chat',false,'chat','panel','data-panel="chat"')}${tool('wave','Wave',false,'wave')}${tool('hand','Raise hand',false,'hand')}<span class="toolbar-separator"></span><div class="toolbar-presence"><strong id="nearby-count"><span class="dot"></span>3 people near you</strong><span>211 people in the hall</span></div><span class="toolbar-separator"></span>${tool('map','Map',false,'map')}${tool('leave','Leave',false,'leave','leave')}</div><div class="hall-zoom">${iconButton('minus','Zoom out','data-action="zoom" data-delta="-0.1"')}<span id="zoom-level">${Math.round(state.zoom*100)}%</span>${iconButton('plus','Zoom in','data-action="zoom" data-delta="0.1"')}</div></main>`;
  }
  function tool(key,label,active=false,i=key,a=key,extra='') { return `<button type="button" class="tool ${active?'active':''} ${key==='leave'?'leave':''}" data-action="${a}" data-tool="${key}" title="${label}" aria-label="${label}" ${['mic','cam','hand'].includes(key)?`aria-pressed="${active}"`:''} ${extra}>${icon(i)}<span>${label}</span></button>`; }
  function panelFrame(title,body) { return `<aside class="hall-panel" aria-label="${title}"><header class="panel-head"><h2>${title}</h2>${iconButton('close','Close panel','data-action="close-panel"')}</header><div class="panel-body">${body}</div></aside>`; }
  function boothBody(index) {
    const p=projects[index];
    return `<div class="flex between"><span class="booth-code">Booth ${p.code}</span>${p.live?status('Presenting'):pill('Away')}</div><h2>${p.title}</h2><div class="panel-subtitle">${p.dept} · Supervised by Dr. Arun</div><p>${p.abstract}</p><div class="project-poster">${poster(p)}</div><div class="resource">${icon('file')}Project overview<small>PDF · 2.4 MB</small>${iconButton('download','Download sample project overview','data-action="download-resource"')}</div><div class="panel-section-title">Meet the presenter</div><div class="person"><img src="assets/characters/${chars[index===0?0:index===1?9:8].id}-portrait.png" width="41" height="41" alt="${p.presenter}"><div><strong>${p.presenter}</strong><small>${p.live?'Available to chat':'Back at 14:30'}</small></div><span class="dot"></span></div><div class="flex" style="margin-top:20px">${action('Ask a question','panel','small','chat','data-panel="chat"')}${action(state.saved.includes(p.code)?'Saved':'Save','save-project','secondary small','bookmark',`data-index="${index}"`)}</div>${action('Share my contact','share-contact','secondary wide small','user',`data-index="${index}" style="margin-top:10px"`)}<p class="field-note" style="margin-top:9px">The booth will receive your name, organisation and email only after you confirm.</p>`;
  }
  function rubricPanel() {
    const p=projects[state.project],locked=!!state.submitted[p.code];
    const values=locked?state.submitted[p.code].values:state.scores;
    const total=values.reduce((a,b)=>a+b,0)/4;
    return panelFrame('Project evaluation',`<div class="flex between"><span class="booth-code">${p.code}</span>${pill(locked?'Scored':'Scoring now',locked?'green':'blue')}</div><h2 style="font-size:1rem">${p.title}</h2><p class="field-note">Choose a score from 1 to 10 for each criterion.</p>${['Technical depth','Problem & impact','Presentation','Feasibility'].map((r,j)=>`<div class="rubric-item"><div class="rubric-label">${r}<span>${values[j]||'–'} / 10</span></div><div class="score-cells" role="group" aria-label="${r}">${Array.from({length:10},(_,i)=>`<button class="score-cell ${i<values[j]?'filled':''}" data-action="score" data-criterion="${j}" data-value="${i+1}" aria-label="${r}: ${i+1} out of 10" aria-pressed="${values[j]===i+1}" ${locked?'disabled':''}>${i+1}</button>`).join('')}</div></div>`).join('')}<label class="field">Private note<textarea id="judge-note" name="judge-note" placeholder="Only you can see this note…" ${locked?'disabled':''}>${escape(locked?state.submitted[p.code].note:state.judgeNote||'')}</textarea></label><div class="rubric-total"><span class="small-text muted">Mean score</span><strong>${total.toFixed(1)}<small> / 10</small></strong></div>${action(locked?'Score submitted':'Submit score','submit-score','wide',locked?'checkCircle':'check',locked?'disabled':'')}<p class="field-note" style="text-align:center;margin-top:10px">Sample scores are saved in this browser.</p>`);
  }
  function panelContent(type) {
    const extension=window.Connecta?.panelView?.(type);if(extension!==undefined)return extension;
    if(type==='booth') return panelFrame(projects[state.project].short,boothBody(state.project));
    if(type==='judge') return rubricPanel();
    if(type==='chat') return panelFrame('Nearby conversation',`<span class="pill green"><span class="dot"></span>3 people nearby</span><p class="field-note" style="margin:12px 0 20px">Only the people close to you can see this conversation.</p><div class="chat-messages" id="chat-messages"><div><div class="chat-name">Prae <span class="muted">13:42</span></div><div class="chat-bubble">Hi! Want to see how our sign-language model works?</div></div><div><div class="chat-name">Phum <span class="muted">13:43</span></div><div class="chat-bubble">Yes, I was just looking at the demo. Does it run offline?</div></div>${state.messages.map(m=>`<div><div class="chat-name">You</div><div class="chat-bubble you">${escape(m)}</div></div>`).join('')}</div><form id="chat-form" class="chat-input"><input name="message" aria-label="Your message" placeholder="Say something…" maxlength="500" required autocomplete="off"><button class="btn small" aria-label="Send message" type="submit">${icon('arrow')}</button></form><p class="field-note" style="margin-top:12px">Preview messages stay in this session only.</p>`);
    if(type==='people') return panelFrame('People in the hall',`<div class="flex between" style="margin-bottom:13px"><strong class="small-text">211 online</strong>${pill('14 nearby','blue')}</div><div class="people-list">${chars.map(c=>`<div class="person"><img src="assets/characters/${c.id}-portrait.png" alt="" width="41" height="41"><div><strong>${c.name}</strong><small>${c.group}</small></div><span class="dot"></span></div>`).join('')}</div>`);
    if(type==='agenda') return panelFrame('Today’s agenda',`<span class="pill blue">Friday, 16 October</span>${sessions.map((s,i)=>`<div style="padding:18px 0;border-bottom:1px solid var(--border)"><span class="small-text muted">${s.start}–${s.end} · ${s.zone}</span><h3 style="font-size:.8125rem;margin:6px 0 11px">${s.title}</h3>${action(i===1?'Join session':'View session','stage','small '+(i===1?'':'secondary'),'arrow')}</div>`).join('')}`);
    if(type==='saved') return panelFrame('Saved projects',state.saved.length?state.saved.map(code=>{const i=projects.findIndex(p=>p.code===code),p=projects[i];return `<button class="project-card" style="margin-bottom:12px;min-height:150px;width:100%" data-action="hall-booth" data-index="${i}"><span class="booth-code">${p.code}</span><h3>${p.title}</h3><p>${p.dept}</p></button>`;}).join(''):empty('Your collection starts here','Open a booth and save a project you want to revisit.'));
    if(type==='settings') return panelFrame('Make it comfortable',`<p>Change the way the hall looks and feels.</p><label class="module-row"><div><h3>Decorative motion</h3><p>NPC walking and character animations</p></div><input type="checkbox" class="switch" ${state.paused?'':'checked'} data-setting="motion" aria-label="Decorative motion"></label><label class="module-row"><div><h3>Microphone preview</h3><p>Show microphone as on or off</p></div><input type="checkbox" class="switch" ${state.mic?'checked':''} data-setting="mic" aria-label="Microphone preview"></label><label class="module-row"><div><h3>Camera preview</h3><p>No device permission is requested</p></div><input type="checkbox" class="switch" ${state.cam?'checked':''} data-setting="cam" aria-label="Camera preview"></label>${btn('Change character','#avatar','secondary wide','user')}<div class="info-note" style="margin-top:18px">${icon('info')}This hall uses your reference image. Movement and conversations are simulated for design review.</div>`);
    return '';
  }
  const sessions=[
    {start:'10:00',end:'10:30',title:'Welcome to a year of possibilities',speaker:'Faculty of Engineering',zone:'Main stage',type:'Opening',past:true},
    {start:'13:30',end:'14:15',title:'Designing for everyday accessibility',speaker:'Dr. Arun Wattanapong',zone:'Main stage',type:'Talk & Q&A',current:true},
    {start:'14:15',end:'15:00',title:'Small steps, big adventures',speaker:'The Pixel Path team',zone:'Booth A07',type:'Project demo'},
    {start:'15:00',end:'15:30',title:'Good ideas start with a conversation',speaker:'Student founders & alumni',zone:'Main stage',type:'Panel discussion'},
    {start:'15:30',end:'16:00',title:'Celebrate what comes next',speaker:'Showcase organising team',zone:'Main stage',type:'Awards & closing'}
  ];
  function agenda() {
    return `${header()}<main id="main" class="page container page-content"><div class="breadcrumb"><a href="#event">Senior Design Showcase 2026</a>${icon('chevron')}<span>Agenda</span></div><div class="section-heading page-title"><div><h1>Make time for a good idea.</h1><p>Talks, demos, and conversations happening around the hall.</p></div>${btn('Enter the hall','#avatar','secondary','arrow')}</div><div class="schedule-layout"><section><div class="tabs"><span class="tab active">Friday, 16 October</span></div><div class="schedule-list">${sessions.map((s,i)=>`<article class="surface session-card ${s.current?'current':''}"><div class="session-time">${s.start}<span>${s.end}</span></div><div class="session-info"><div class="flex between">${s.current?status('Happening now'):pill(s.past?'Ended':s.type)}${iconButton(state.scheduleSaved.includes(i)?'checkCircle':'bookmark',state.scheduleSaved.includes(i)?'Remove session reminder':'Save session',`data-action="save-session" data-index="${i}"`)}</div><h3>${s.title}</h3><p>${s.speaker}</p><div class="flex between" style="margin-top:17px"><span class="small-text muted flex">${icon('pin')}${s.zone}</span>${s.current?btn('Join session','#hall','small','arrow'):action('Session details','session-details','secondary small','info',`data-index="${i}"`)}</div></div></article>`).join('')}</div></section><aside><div class="speaker-card">${pill('On the main stage','light')}${actor(10,{})}<h2>Designing for everyone starts with listening.</h2><p>Join Dr. Arun for a conversation about accessible design, the people it serves, and what we can do better.</p><div class="small-text" style="margin-bottom:18px">13:30–14:15 · Main stage</div>${btn('Join the conversation','#hall','wide','arrow')}</div></aside></div></main>`;
  }
  function sidebar(kind='organizer') {
    const links=kind==='presenter'?[['presenter','My booth','monitor'],['hall','Visit the hall','map'],['profile','My contacts','users'],['schedule','Agenda','calendar']]:[['organizer','Overview','grid'],['create-event','Event setup','settings'],['event','Projects & booths','monitor'],['schedule','Agenda','calendar'],['analytics','Event report','chart'],['judge','Judging','trophy']];
    return `<aside class="sidebar"><div class="sidebar-caption">${kind==='presenter'?'Presenter workspace':'Your showcase'}</div>${links.map(([r,l,i])=>`<a href="#${r}" class="${state.route===r?'active':''}" title="${l}">${icon(i)}<span>${l}</span></a>`).join('')}<div class="sidebar-event">${status('Event is live')}<p>Senior Design Showcase 2026<br>16 Oct · 10:00–16:00</p></div></aside>`;
  }
  const workspace = (body,kind) => `${header()}<div class="workspace page">${sidebar(kind)}<main id="main" class="workspace-main">${body}</main></div>`;
  function kpis(items) { return `<div class="kpi-grid">${items.map(([l,v,n,i])=>`<div class="surface kpi"><div class="kpi-label">${l}${icon(i||'chart')}</div><div class="kpi-value">${v}</div><div class="kpi-note">${n}</div></div>`).join('')}</div>`; }
  function analytics() {
    const rankings=[[1,1,'8.9',5],[2,4,'8.6',5],[3,0,'8.4',4],[4,5,'8.1',5],[5,2,'7.9',4],[6,3,'7.7',5]];
    return workspace(`<div class="breadcrumb"><a href="#organizer">Your showcase</a>${icon('chevron')}<span>Event report</span></div><div class="section-heading"><div><h1>Every connection, counted.</h1><p>Senior Design Showcase 2026 · Fri 16 Oct · Sample event report</p></div><div class="flex">${action('Export CSV','export','secondary small','download')}${action('Publish results','publish','small','globe')}</div></div>${kpis([['Registered','612','+18% from last year','users'],['Attended','438','72% turnout','checkCircle'],['Peak in hall','211','At 13:30 ICT','chart'],['Avg. time in hall','47 min','6.2 booths visited each','clock']])}<div class="analytics-grid"><div class="stack"><section class="surface chart-card"><div class="chart-head"><h3>People in the hall</h3>${pill('Today','blue')}</div><div class="chart" role="img" aria-label="Sample attendance rises from 68 at 10:00 to a peak of 211 at 13:30, ending at 63 at 16:00">${[32,48,66,74,70,58,80,100,92,76,54,30].map((v,i)=>`<div class="chart-bar" style="--bar:${v}%;--delay:${i*25}ms"><span class="chart-tip">${Math.round(v*2.11)} people</span></div>`).join('')}</div><div class="chart-labels"><span>10:00</span><span>11:00</span><span>12:00</span><span>13:00</span><span>14:00</span><span>15:00</span><span>16:00</span></div></section><section class="surface chart-card"><div class="chart-head"><h3>Most visited booths</h3><small>Unique visitors</small></div><div class="booth-bars">${[['A07',188],['C05',164],['A01',151],['B03',127],['B09',119]].map(([code,n])=>`<div class="booth-bar-row"><span>${code}</span><div class="bar-track"><div class="bar-fill" style="--bar:${n/188*100}%"></div></div><strong>${n}</strong></div>`).join('')}</div></section></div><section class="surface chart-card"><div class="chart-head"><h3>Judging results</h3><small>Mean score / 10</small></div>${rankings.map(([rank,p,score,n])=>`<div class="ranking-row"><span class="rank-num">${rank}</span><div class="rank-info"><strong>${projects[p].title}</strong><small>${projects[p].code} · ${n} judges</small></div><span class="rank-score">${score}</span></div>`).join('')}<div class="info-note" style="margin-top:18px">${icon('shield')}Results stay private until the organizer publishes them.</div></section></div>`);
  }
  function organizer() {
    return workspace(`<div class="section-heading"><div><div class="flex" style="margin-bottom:8px">${status('Live now')}${pill('Organizer','blue')}</div><h1>A space full of possibilities.</h1><p>Senior Design Showcase 2026 · Your event at a glance.</p></div>${btn('Visit the hall','#hall','small','arrow')}</div>${kpis([['Registered','612','34 joined today','users'],['In the hall','211','31 booths presenting','globe'],['Booths','42','3 away at the moment','monitor'],['Sessions','5','1 happening now','calendar']])}<div class="workspace-grid"><section class="surface"><div class="panel-card" style="padding-bottom:15px"><div class="flex between"><h2 style="font-size:1.1rem">Your people</h2>${action('Invite people','invite','small','plus')}</div><p class="field-note" style="margin-top:7px">Event roles are assigned here. A person can have more than one role.</p></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Event role</th><th>Status</th><th></th></tr></thead><tbody>${[['Dr. Arun Wattanapong','Speaker','Online','AW'],['Prae Srisuwan','Presenter','At booth A07','PS'],['Dr. Pim Rattanakul','Judge','In the hall','PR'],['Fah Chaiyaporn','Staff','Online','FC']].map(([n,r,s,i])=>`<tr><td><span class="table-person"><span class="avatar-dot">${i}</span>${n}</span></td><td>${pill(r,r==='Judge'?'blue':'')}</td><td><span class="small-text" style="color:var(--green)">${s}</span></td><td>${iconButton('more','Manage '+n,`data-action="manage-person" data-name="${n}"`)}</td></tr>`).join('')}</tbody></table></div></section><div class="stack"><section class="surface panel-card"><h2>What is in your event?</h2>${moduleRows()}<p class="field-note" style="margin-top:15px">These switches preview event modules. Changes are stored locally.</p></section><section class="surface panel-card"><div class="flex between"><h3 style="font-size:.875rem">Next on the agenda</h3>${icon('calendar')}</div><p class="body-text" style="margin:12px 0">14:15 · Small steps, big adventures</p>${btn('Manage agenda','#schedule','secondary small','arrow')}</section></div></div>`);
  }
  function moduleRows() {
    return [['booths','Exhibition booths','Projects, presenters and resources'],['meetings','Meeting rooms','A quieter space for conversations'],['qa','Live Q&A','Questions for the main stage'],['sponsors','Sponsors','Give event partners a place to be seen']].map(([k,t,p])=>`<label class="module-row"><div><h3>${t}</h3><p>${p}</p></div><input type="checkbox" class="switch" aria-label="${t}" data-module="${k}" ${state.modules[k]?'checked':''}></label>`).join('');
  }
  function createEvent() {
    const d=state.eventDraft;
    return workspace(`<div class="breadcrumb"><a href="#organizer">Your showcase</a>${icon('chevron')}<span>Create an event</span></div><div class="section-heading"><div><h1>Make room for your ideas.</h1><p>A few details, a shared space, and you are ready to bring people together.</p></div>${action('Save draft','save-event','secondary small','save')}</div><div class="setup-stepper"><div class="setup-step active"><span>1</span>Event details</div><i class="setup-line"></i><div class="setup-step"><span>2</span>Your space</div><i class="setup-line"></i><div class="setup-step"><span>3</span>Review & share</div></div><div class="workspace-grid"><form id="create-event-form" class="surface panel-card stack"><h2 style="margin-bottom:0">Start with the essentials.</h2><label class="field">Event name<input name="title" id="new-event-title" value="${escape(d.title||'Senior Design Showcase 2026')}" placeholder="Give your showcase a name…" required maxlength="100"></label><label class="field">Description<textarea name="description" placeholder="What will people discover at your event?…" required>${escape(d.description||'A year of student ideas, brought together in one shared space. Meet the creators and explore what comes next.')}</textarea></label><div class="form-row"><label class="field">Date<input type="date" name="date" value="${escape(d.date||'2026-10-16')}" required></label><label class="field">Time zone<select name="timezone"><option>Asia/Bangkok (UTC+7)</option></select></label></div><div class="form-row"><label class="field">Start time<input type="time" name="start" value="${escape(d.start||'10:00')}" required></label><label class="field">End time<input type="time" name="end" value="${escape(d.end||'16:00')}" required></label></div><label class="field">Who can join?<select name="access"><option ${d.access==='Public'?'selected':''}>Public</option><option ${d.access==='Invite only'?'selected':''}>Invite only</option></select><span class="field-note">Everyone signs in with an account. Invite-only events also check the guest list.</span></label><label class="upload-area">${icon('upload')}Add an event cover<input type="file" name="cover" accept="image/png,image/jpeg,image/webp" aria-label="Choose event cover"></label><button class="btn" type="submit">Review event ${icon('arrow')}</button></form><aside><section class="surface panel-card setup-preview"><img src="assets/maps/exhibition/minimap.png" alt="Exhibition hall preset preview" width="1536" height="855"><h2 style="font-size:1.125rem">A space that fits your event.</h2><p class="body-text">The exhibition hall brings a main stage, three booth zones, and a meeting room together.</p><div class="setup-map-grid">${['Exhibition hall','Community meetup','Talk & workshop'].map((n,i)=>`<button class="map-option ${i===0?'active':''}" type="button" data-action="map-preset" data-index="${i}" aria-pressed="${i===0}"><img src="assets/images/${i===0?'../maps/exhibition/minimap.png':i===1?'step-2.png':'step-3.png'}" alt="" width="160" height="100"><span>${n}</span></button>`).join('')}</div><h3 style="font-size:.875rem;margin-top:24px">Choose your modules</h3>${moduleRows()}</section></aside></div>`);
  }
  function presenter() {
    return workspace(`<div class="section-heading"><div><div class="flex" style="margin-bottom:9px">${pill('Presenter workspace','blue')}<span class="booth-code">A07 · Pixel Path</span></div><h1>Tell the story behind your work.</h1><p>Keep your booth ready for the next curious mind.</p></div>${btn('Preview in the hall','#hall','secondary small','arrow')}</div>${kpis([['Booth visitors','188','24 in the last hour','users'],['Avg. visit','6.2 min','Time well spent','clock'],['Shared contacts','32','5 new connections today','user'],['Resource downloads','74','Project overview is most popular','download']])}<div class="workspace-grid"><form id="booth-form" class="surface panel-card stack"><h2 style="margin-bottom:0">Your booth</h2><label class="field">Project title<input name="title" value="${escape(state.booth.title)}" required maxlength="120"></label><label class="field">Project abstract<textarea name="abstract" required maxlength="1200">${escape(state.booth.abstract)}</textarea></label><label class="field">Project website<input name="link" type="url" value="${escape(state.booth.link)}" placeholder="https://your-project.example…"></label><label class="field">Availability<select name="status">${['Available','Busy','Away'].map(s=>`<option ${state.booth.status===s?'selected':''}>${s}</option>`).join('')}</select><span class="field-note">People can see this before they approach your booth.</span></label><div><h3 style="font-size:.875rem;margin-bottom:10px">Resources</h3><div class="resource">${icon('file')}Project overview.pdf<small>2.4 MB</small>${iconButton('download','Download project resource','data-action="download-resource"')}</div><label class="upload-area" style="display:block;margin-top:14px">${icon('upload')}Add a resource<input type="file" name="resource" accept=".pdf,.png,.jpg,.webp" aria-label="Choose project resource"></label></div><button class="btn" type="submit">${icon('save')} Save booth</button></form><aside class="stack"><section class="surface panel-card"><div class="flex between"><h3 style="font-size:.875rem">Your booth preview</h3>${pill(state.booth.status,'green')}</div><div class="project-poster">${poster(projects[1])}</div><h3>${escape(state.booth.title)}</h3><p class="body-text" style="margin-top:12px">${escape(state.booth.abstract)}</p></section><section class="surface panel-card"><div class="flex between"><h3 style="font-size:.875rem">Recent connections</h3>${action('Export','export-leads','ghost small','download')}</div>${[8,0,11].map(i=>`<div class="person"><img src="assets/characters/${chars[i].id}-portrait.png" alt="" width="41" height="41"><div><strong>${chars[i].name}</strong><small>Shared contact · today</small></div>${icon('checkCircle')}</div>`).join('')}<p class="field-note" style="margin-top:13px">Only people who confirmed sharing their details appear here.</p></section></aside></div>`,'presenter');
  }
  function profile() {
    const p=state.profile;
    return `${header()}<main id="main" class="page container narrow page-content"><div class="page-title"><h1>A familiar face in every room.</h1><p>Choose what people see and how they can connect with you.</p></div><div class="profile-layout"><aside class="surface profile-summary">${actor(state.avatar,{})}<div><h2>${escape(state.name)}</h2><p>${escape(p.organisation||'King Mongkut’s University of Technology Thonburi')}</p>${btn('Change character','#avatar','secondary small','user')}</div></aside><form id="profile-form" class="surface profile-form"><div class="flex between" style="margin-bottom:20px"><h2 style="margin:0">Your public profile</h2>${pill('Visible in the hall','blue')}</div><div class="form-row"><label class="field">Display name<input name="name" value="${escape(state.name)}" autocomplete="nickname" required maxlength="30"></label><label class="field">Position<input name="position" value="${escape(p.position||'IT student')}" autocomplete="organization-title" maxlength="80"></label></div><label class="field">University or organisation<input name="organisation" value="${escape(p.organisation||'KMUTT')}" autocomplete="organization" maxlength="120"></label><label class="field">A little about you<textarea name="bio" placeholder="What are you curious about?…" maxlength="500">${escape(p.bio||'Curious about thoughtful interfaces, interactive worlds, and the people who use them.')}</textarea></label><label class="field">Interests<input name="interests" value="${escape(p.interests||'Design, web development, games')}" placeholder="e.g. accessibility, design, AI…" maxlength="160"></label><div class="flex between" style="margin:30px 0 18px"><h2 style="margin:0">Private contact details</h2>${pill('Shared by consent','green')}</div><div class="form-row"><label class="field">Email<input name="email" type="email" autocomplete="email" value="${escape(p.email||'nont@example.com')}" required spellcheck="false"></label><label class="field">LinkedIn or website<input name="website" type="url" autocomplete="url" value="${escape(p.website||'')}" placeholder="https://…"></label></div><label class="module-row"><div><h3>Make my contact details visible to everyone</h3><p>Off by default. Otherwise, exchange contacts before sharing.</p></div><input type="checkbox" name="publicContacts" class="switch" ${p.publicContacts?'checked':''} aria-label="Make contact details public"></label><label class="module-row"><div><h3>Accept contact requests</h3><p>Let people ask to exchange their details with you.</p></div><input type="checkbox" name="acceptRequests" class="switch" ${p.acceptRequests===false?'':'checked'} aria-label="Accept contact requests"></label><button class="btn" type="submit" style="margin-top:22px">${icon('save')} Save profile</button></form></div><section style="margin-top:36px"><div class="section-heading"><div><h2>Good people to keep in touch with.</h2><p>Your sample connections from this showcase.</p></div>${action('Download contacts','download-contacts','secondary small','download')}</div><div class="contact-grid">${[9,8,10].map(i=>`<article class="surface contact-card"><img src="assets/characters/${chars[i].id}-portrait.png" alt="" width="46" height="46"><div><h3>${chars[i].name}</h3><p>Connected at the showcase</p></div></article>`).join('')}</div></section></main>`;
  }

  let toastTimer;
  function toast(message) { const el=$('#toast'); el.textContent=message; el.classList.add('visible'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.classList.remove('visible'),3200); }
  const modal=$('#modal');
  let modalInvoker=null;
  function openModal(html,cls='') { modalInvoker=document.activeElement; if(modal.open) modal.close(); modal.className='modal '+cls; modal.innerHTML=`${iconButton('close','Close dialog','data-action="close-modal"')}${html}`; const close=$('[data-action="close-modal"]',modal); close.classList.add('modal-close'); modal.showModal(); }
  function closeModal() { modal.close(); modal.innerHTML=''; if(modalInvoker?.isConnected) modalInvoker.focus({preventScroll:true}); }
  modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect(); if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
  modal.addEventListener('cancel',()=>{if(modalInvoker?.isConnected)modalInvoker.focus({preventScroll:true});});
  function go(route) { if(location.hash==='#'+route)render(); else location.hash=route; }
  function setPanel(type) { state.panel=type; const el=$('#hall-panel-container'); if(el)el.innerHTML=type?panelContent(type):''; document.dispatchEvent(new CustomEvent('connecta:panel',{detail:{type}})); }
  function videoTiles() { return ''; }
  function showProject(i) { state.project=i; openModal(`<div class="flex between"><span class="booth-code">${projects[i].code}</span>${status('Presenting')}</div><h2 id="modal-title" style="margin:18px 0 8px">${projects[i].title}</h2><p>${projects[i].abstract}</p><div class="project-poster">${poster(projects[i])}</div><div class="modal-footer">${action(state.saved.includes(projects[i].code)?'Saved':'Save project','save-project','secondary','bookmark',`data-index="${i}"`)}${btn('Visit the booth','#hall','','arrow')}</div>`); }
  function tour() { const slides=[['A hall full of possibilities.','Browse booths, join a talk, and meet the people behind the ideas. All in one shared space.','../maps/exhibition/minimap.png'],['A character that feels like you.','Pick one of 14 characters. Use WASD or the arrow keys to walk around the hall.','step-2.png'],['Walk a little closer.','Approach a booth to explore its project. In the finished experience, nearby people can talk through proximity audio.','step-3.png']]; const [h,p,img]=slides[state.tour];openModal(`<div class="tour-slide"><img class="tour-illustration" src="assets/images/${img}" width="600" height="350" alt="${h}"><h2 id="modal-title">${h}</h2><p>${p}</p><div class="tour-dots" aria-label="Step ${state.tour+1} of 3">${slides.map((_,i)=>`<span class="${i===state.tour?'active':''}"></span>`).join('')}</div>${action(state.tour===2?'Explore events':'Next','tour-next','wide','arrow')}</div>`); }
  function download(filename,content,type='text/csv;charset=utf-8') { const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000); }
  function showPages() { openModal(`<h2 id="modal-title">Take a look around.</h2><p>${pages.length} screens in one interactive preview. Switch roles and explore the complete design.</p><div class="page-links">${pages.filter(([r])=>window.Connecta?.pageVisible?.(r)!==false).map(([r,n,d,i])=>`<a class="page-link ${state.route===r?'current':''}" href="#${r}" data-close-dialog>${icon(i)}<div>${n}<small>${d}</small></div></a>`).join('')}</div><p class="field-note" style="margin:22px 0 0">HTML design preview · sample data · sample accounts and local feature data · LiveKit media available in the hall</p>`,'page-picker'); }
  function updatePreviewTools() { $('#preview-tools').innerHTML=`<button data-action="pages">${icon('grid')}All screens <span style="color:var(--faint)">${pages.length}</span></button><button class="motion-btn" data-action="motion" aria-pressed="${!state.paused}" title="${state.paused?'Resume animations':'Pause animations'}">${icon(state.paused?'play':'pause')}${state.paused?'Resume':'Motion on'}</button><span class="preview-label">Interactive UI preview</span>`; document.body.classList.toggle('motion-paused',state.paused); }
  function toggleMotion() { state.paused=!state.paused;save('paused',state.paused);updatePreviewTools();const hallButton=$('[data-hall-motion]');if(hallButton){hallButton.innerHTML=icon(state.paused?'play':'pause');hallButton.setAttribute('aria-label',state.paused?'Resume hall animation':'Pause hall animation');hallButton.title=state.paused?'Resume hall animation':'Pause hall animation';}document.dispatchEvent(new CustomEvent('connecta:motion')); }
  function render() {
    state.route=location.hash.replace('#','').split('?')[0]||'home';
    if(!pages.some(p=>p[0]===state.route))state.route='home';
    if(modal.open)closeModal();
    state.panel=state.route==='judge'?'judge':null;
    const views={home,events,signup:()=>auth(),signin:()=>auth(true),event:eventPage,avatar:lobby,hall:()=>hall(),judge:()=>hall(true),schedule:agenda,analytics,organizer,'create-event':createEvent,presenter,profile,...window.Connecta.extraViews};
    document.body.classList.toggle('in-hall',['hall','judge'].includes(state.route));
    $('#app').innerHTML=views[state.route]();
    if(['hall','judge'].includes(state.route)) {
      const main=$('#main');main.tabIndex=0;main.insertAdjacentHTML('afterbegin',`<h1 class="sr-only">${state.route==='judge'?'Judge':'Visitor'} exhibition hall</h1>`);main.focus({preventScroll:true});
      $('.hall-left-tools').insertAdjacentHTML('beforeend',iconButton(state.paused?'play':'pause',state.paused?'Resume hall animation':'Pause hall animation','data-action="motion" data-hall-motion'));
    }
    document.title=`${pages.find(p=>p[0]===state.route)[1]} · Connecta`;
    updatePreviewTools();
    if($('#project-search'))$('#project-search').value=state.projectSearch;
    if($('#event-search'))$('#event-search').value=state.eventSearch;
    window.scrollTo({top:0,behavior:'instant'});
    document.dispatchEvent(new CustomEvent('connecta:render'));
  }
  document.addEventListener('click',e=>{
    const b=e.target.closest('[data-action]');
    if(e.target.closest('[data-close-dialog]')&&modal.open)closeModal();
    if(!b)return;
    const a=b.dataset.action, n=Number(b.dataset.index||0);
    if(a==='pages')showPages();
    else if(a==='motion')toggleMotion();
    else if(a==='close-modal')closeModal();
    else if(a==='tour'){state.tour=0;tour();}
    else if(a==='tour-next'){if(state.tour===2){closeModal();go('events');}else{state.tour++;tour();}}
    else if(a==='role'){state.role=b.dataset.value;document.querySelectorAll('.role-segment button').forEach(el=>{const on=el.dataset.value===state.role;el.classList.toggle('active',on);el.setAttribute('aria-pressed',on);});$('#role-note').textContent=state.role==='Visitor'?'Explore the showcase and meet the creators.':'Event roles are granted by the organizer. This selector previews the role only.';}
    else if(a==='sso')openModal(`<h2 id="modal-title">Continue with your university.</h2><p>In the finished app, your university account signs you in securely. For this preview, continue with sample details.</p>${action('Continue as '+escape(state.name),'sample-login','wide','shield')}`);
    else if(a==='sample-login'){closeModal();go('event');toast('You are viewing a sample account.');}
    else if(a==='project-filter'){state.department=b.dataset.value;document.querySelectorAll('[data-action="project-filter"]').forEach(el=>{const on=el===b;el.classList.toggle('active',on);el.setAttribute('aria-pressed',on);});$('#project-results').innerHTML=projectResults();}
    else if(a==='event-filter'){state.eventFilter=b.dataset.value;document.querySelectorAll('[data-action="event-filter"]').forEach(el=>{const on=el===b;el.classList.toggle('active',on);el.setAttribute('aria-pressed',on);});$('#event-results').innerHTML=eventResults();document.dispatchEvent(new CustomEvent('connecta:refresh'));}
    else if(a==='project')showProject(n);
    else if(a==='avatar'){state.avatar=n;save('avatar',n);document.querySelectorAll('.character-option').forEach(el=>{const on=Number(el.dataset.index)===n;el.classList.toggle('active',on);el.setAttribute('aria-pressed',on);});$('#selected-avatar').innerHTML=actor(n,{name:state.name,walk:state.avatarWalking,direction:state.direction});document.dispatchEvent(new CustomEvent('connecta:refresh'));}
    else if(a==='avatar-turn'||a==='avatar-walk'){if(a==='avatar-turn')state.direction=Number(b.dataset.direction);else state.avatarWalking=!state.avatarWalking;$('#selected-avatar').innerHTML=actor(state.avatar,{name:state.name,walk:state.avatarWalking,direction:state.direction});document.dispatchEvent(new CustomEvent('connecta:refresh'));}
    else if(a==='enter-hall'){const input=$('#display-name');if(!input.value.trim()){input.setCustomValidity('Enter a display name to continue.');input.reportValidity();return;}input.setCustomValidity('');state.name=input.value.trim();save('name',state.name);if(!state.registered){openModal(`<h2 id="modal-title">Your place is waiting.</h2><p>Register for Senior Design Showcase 2026 with your sample profile. Your account and event registration are separate.</p><div class="info-note">${icon('user')}You will join as ${escape(state.name)}, a visitor.</div><div class="modal-footer">${action('Register & enter','confirm-register','','arrow')}</div>`);}else go('hall');}
    else if(a==='confirm-register'){state.registered=true;save('registered',true);closeModal();go('hall');toast('Welcome to the showcase. Walk up and say hello.');}
    else if(a==='hall-booth'){state.project=n;state.scores=[0,0,0,0];state.judgeNote='';setPanel(state.route==='judge'?'judge':'booth');}
    else if(a==='panel')setPanel(state.panel===b.dataset.panel?null:b.dataset.panel);
    else if(a==='close-panel'){setPanel(null);$('#video-area').innerHTML='';}
    else if(a==='mic'||a==='cam'){state[a]=!state[a];const el=$(`[data-tool="${a}"]`);if(el){el.classList.toggle('active',state[a]);el.setAttribute('aria-pressed',state[a]);el.setAttribute('aria-label',a==='mic'?(state.mic?'Microphone on':'Microphone off'):(state.cam?'Camera on':'Camera off'));el.innerHTML=icon(a==='mic'?(state.mic?'mic':'micOff'):(state.cam?'video':'videoOff'))+`<span>${a==='mic'?(state.mic?'Mic on':'Mic off'):(state.cam?'Camera on':'Camera off')}</span>`;}toast(`${a==='mic'?'Microphone':'Camera'} ${state[a]?'on':'off'} in preview. No device is accessed.`);}
    else if(a==='wave'){window.ConnectaMotion?.emote('👋');toast('You waved to the people nearby.');}
    else if(a==='hand'){const on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',on);b.classList.toggle('active',on);if(on)window.ConnectaMotion?.emote('✋');toast(on?'Your hand is raised. The speaker can see your request.':'Your hand is lowered.');}
    else if(a==='zoom'){state.zoom=Math.max(.8,Math.min(1.5,Math.round((state.zoom+Number(b.dataset.delta))*10)/10));$('#hall-world').style.setProperty('--zoom',state.zoom);$('#zoom-level').textContent=Math.round(state.zoom*100)+'%';}
    else if(a==='map')openModal(`<h2 id="modal-title">Find your way.</h2><p>Choose a destination to focus on its details.</p><div class="modal-map"><img src="assets/maps/exhibition/minimap.png" width="1536" height="855" alt="Full exhibition map"><button class="map-pin" style="left:12%;top:14%" data-action="map-destination" data-index="0">A01</button><button class="map-pin" style="left:12%;top:43%" data-action="map-destination" data-index="1">A07</button><button class="map-pin" style="left:12%;top:70%" data-action="map-destination" data-index="2">B03</button><button class="map-pin" style="left:45%;top:15%" data-action="stage">Stage</button></div>`);
    else if(a==='map-destination'){closeModal();state.project=n;setPanel(state.route==='judge'?'judge':'booth');window.ConnectaMotion?.moveTo(33,23+n*25);}
    else if(a==='leave')openModal(`<h2 id="modal-title">Step out of the hall?</h2><p>Your saved projects and sample scores will be here when you return.</p><div class="modal-footer">${action('Stay here','close-modal','secondary')}${btn('Leave the hall','#event','','leave')}</div>`);
    else if(a==='hall-help')openModal(`<h2 id="modal-title">A little closer is all it takes.</h2><p>Move with WASD or the arrow keys. Walk up to a booth and click it to learn more, or choose a destination on the map.</p><div class="info-note">${icon('info')}This design uses the supplied map image. NPCs and your character animate here; proximity calls are a preview.</div><div class="modal-footer">${action('Got it','close-modal','','check')}</div>`);
    else if(a==='score'){state.scores[Number(b.dataset.criterion)]=Number(b.dataset.value);state.judgeNote=$('#judge-note')?.value||'';setPanel('judge');}
    else if(a==='submit-score'){if(state.scores.some(v=>!v)){toast('Choose a score for all four criteria first.');return;}const code=projects[state.project].code;state.submitted[code]={values:[...state.scores],note:$('#judge-note')?.value||''};save('scores',state.submitted);setPanel('judge');$('#judge-progress').textContent=Object.keys(state.submitted).length+' of 12 scored';toast('Score submitted. Your evaluation is saved in this browser.');}
    else if(a==='save-project'){const code=projects[n].code;const had=state.saved.includes(code);state.saved=had?state.saved.filter(x=>x!==code):[...state.saved,code];save('saved',state.saved);b.innerHTML=icon('bookmark')+(had?'Save project':'Saved');toast(had?'Project removed from your collection.':'Project saved to your collection.');}
    else if(a==='share-contact')openModal(`<h2 id="modal-title">Share your contact with ${projects[n].short}?</h2><p>The booth will receive your name, organisation and email. You can keep browsing without sharing.</p><div class="surface" style="padding:18px"><strong>${escape(state.name)}</strong><p class="small-text">${escape(state.profile.organisation||'KMUTT')}<br>${escape(state.profile.email||'nont@example.com')}</p></div><div class="modal-footer">${action('Keep browsing','close-modal','secondary')}${action('Share my contact','confirm-contact','','user')}</div>`);
    else if(a==='confirm-contact'){closeModal();toast('Sample contact shared. You can keep exploring.');}
    else if(a==='stage')openModal(`<div class="flex" style="margin-bottom:16px">${status('Live on the main stage')}</div><h2 id="modal-title">Designing for everyday accessibility</h2><p>Dr. Arun Wattanapong · 13:30–14:15</p><div class="camera-preview" style="aspect-ratio:1.6"><span>${icon('monitor')}</span><strong>Speaker’s shared screen</strong><span style="font-size:.625rem">Streaming preview · no live video connected</span></div><div class="flex between"><span class="small-text muted">86 people listening</span>${action('Ask a question','stage-question','small','chat')}</div>`);
    else if(a==='stage-question')openModal(`<h2 id="modal-title">What are you curious about?</h2><p>Your question appears in the session Q&A.</p><form id="question-form" class="stack"><label class="field">Your question<textarea name="question" required maxlength="500" placeholder="Ask the speaker…"></textarea></label><button class="btn" type="submit">Send question ${icon('arrow')}</button></form>`);
    else if(a==='meeting')openModal(`<h2 id="modal-title">A quieter place to talk.</h2><p>Meeting room · 2 seats available. Entering would move your conversation into this private room.</p><div class="meeting-preview"><div class="meeting-seat"><img src="assets/characters/${chars[state.avatar].id}-portrait.png" width="70" height="70" alt="Your character"><span>You</span></div><div class="meeting-seat">${icon('plus')}<span>Available seat</span></div></div><div class="modal-footer">${action('Maybe later','close-modal','secondary')}${action('Enter room','enter-meeting','','arrow')}</div>`);
    else if(a==='enter-meeting'){closeModal();toast('You entered the sample meeting room.');setPanel('chat');window.ConnectaMotion?.moveTo(82,23);}
    else if(a==='save-session'){const had=state.scheduleSaved.includes(n);state.scheduleSaved=had?state.scheduleSaved.filter(x=>x!==n):[...state.scheduleSaved,n];save('schedule',state.scheduleSaved);b.innerHTML=icon(had?'bookmark':'checkCircle');toast(had?'Session removed from your agenda.':'Session saved to your agenda.');}
    else if(a==='session-details'){const s=sessions[n];openModal(`<h2 id="modal-title">${s.title}</h2><p>${s.start}–${s.end} · ${s.zone}</p><div class="info-note">${icon('calendar')}With ${s.speaker}. Explore the session and meet the speaker in the hall.</div><div class="modal-footer">${btn('Enter the hall','#hall','','arrow')}</div>`);}
    else if(a==='event-about')openModal(`<h2 id="modal-title">A year of ideas, together.</h2><p>Senior Design Showcase 2026 brings student projects and curious visitors into one shared virtual hall. Explore 42 booths, hear from the creators and meet your next collaborator.</p><div class="info-note">${icon('calendar')}Friday, 16 October 2026 · 10:00–16:00 ICT</div>`);
    else if(a==='export'){download('connecta-event-report-sample.csv','\uFEFFMetric,Value\r\nRegistered,612\r\nAttended,438\r\nPeak in hall,211\r\nAverage visit (minutes),47\r\n\r\nBooth,Unique visitors\r\nA07,188\r\nC05,164\r\nA01,151\r\nB03,127\r\nB09,119\r\n');toast('Sample event report downloaded.');}
    else if(a==='export-leads'){download('connecta-booth-contacts-sample.csv','Name,Organisation,Email\r\nPhum,Example University,phum@example.com\r\nMika,Example University,mika@example.com\r\n');toast('Sample booth contacts downloaded.');}
    else if(a==='download-contacts'){download('connecta-sample-contacts.vcf','BEGIN:VCARD\r\nVERSION:3.0\r\nFN:Prae Srisuwan\r\nORG:Example University\r\nEMAIL:prae@example.com\r\nEND:VCARD\r\n','text/vcard');toast('Sample vCard downloaded.');}
    else if(a==='download-resource'){download('connecta-project-overview-sample.txt','Connecta sample project overview\n\n'+projects[state.project].title+'\n\n'+projects[state.project].abstract+'\n\nThis is a design preview resource, not a submitted project document.','text/plain;charset=utf-8');toast('Sample project overview downloaded.');}
    else if(a==='publish')openModal(`<h2 id="modal-title">Publish the sample results?</h2><p>In the finished app, this makes judging results visible to attendees. Here it changes the local preview state only.</p><div class="modal-footer">${action('Keep private','close-modal','secondary')}${action('Publish sample results','confirm-publish','','globe')}</div>`);
    else if(a==='confirm-publish'){closeModal();toast('Sample results published in this preview.');}
    else if(a==='invite')openModal(`<h2 id="modal-title">Bring someone into the room.</h2><p>Invite a speaker, exhibitor, judge or staff member to your event.</p><form id="invite-form" class="stack"><label class="field">Email address<input name="email" type="email" autocomplete="email" required placeholder="colleague@university.ac.th…"></label><label class="field">Event role<select name="role"><option>Speaker</option><option>Presenter</option><option>Judge</option><option>Staff</option></select></label><button type="submit" class="btn">Preview invitation ${icon('mail')}</button></form>`);
    else if(a==='manage-person')openModal(`<h2 id="modal-title">${escape(b.dataset.name)}</h2><p>Event roles are managed by the organizer. Staff can assign Speaker and Presenter roles.</p><div class="info-note">${icon('shield')}This is a role-management design preview. No account permissions are changed.</div>`);
    else if(a==='map-preset'){document.querySelectorAll('.map-option').forEach(el=>{const on=el===b;el.classList.toggle('active',on);el.setAttribute('aria-pressed',on);});toast(n===0?'Exhibition hall selected.':'Preset selected for preview. The supplied map remains the exhibition reference.');}
    else if(a==='save-event')saveEvent(false);
    else if(a==='notifications')openModal(`<h2 id="modal-title">A few things to catch up on.</h2><p>You are all set for Senior Design Showcase 2026.</p><div class="resource">${icon('calendar')}Designing for everyday accessibility is live.</div><div class="resource">${icon('users')}Prae accepted your sample contact request.</div>`);
  });
  function saveEvent(review) {
    const form=$('#create-event-form');if(!form.reportValidity())return;
    const data=Object.fromEntries(new FormData(form));delete data.cover;
    if(data.end<=data.start){toast('Choose an end time after the start time.');return;}
    state.eventDraft=data;save('event-draft',data);
    if(review)openModal(`<h2 id="modal-title">${escape(data.title)}</h2><p>${escape(data.description)}</p><div class="info-note">${icon('calendar')}${escape(data.date)} · ${escape(data.start)}–${escape(data.end)} · ${escape(data.access)}</div><div class="modal-footer">${action('Keep editing','close-modal','secondary')}${action('Save preview event','event-created','','check')}</div>`);
    else toast('Event draft saved in this browser.');
  }
  document.addEventListener('click',e=>{if(e.target.closest('[data-action="event-created"]')){closeModal();go('organizer');toast('Sample event saved. No event was published online.');}});
  document.addEventListener('input',e=>{
    if(e.target.id==='project-search'){state.projectSearch=e.target.value;$('#project-results').innerHTML=projectResults();$('#project-count').textContent=$$('.project-card','#project-results').length+' featured projects';}
    if(e.target.id==='event-search'){state.eventSearch=e.target.value;$('#event-results').innerHTML=eventResults();document.dispatchEvent(new CustomEvent('connecta:refresh'));}
    if(e.target.id==='display-name'){state.name=e.target.value;const tag=$('#selected-avatar .name-tag');if(tag)tag.textContent=state.name||'You';e.target.setCustomValidity('');}
  });
  function $$(q,root=document) {return [...(typeof root==='string'?$(root):root).querySelectorAll(q)];}
  document.addEventListener('change',e=>{
    if(e.target.dataset.module){state.modules[e.target.dataset.module]=e.target.checked;save('modules',state.modules);toast('Event module setting saved in this preview.');}
    const setting=e.target.dataset.setting;
    if(setting==='motion'){state.paused=e.target.checked;toggleMotion();}
    if(setting==='mic'||setting==='cam'){state[setting]=e.target.checked;const camera=$('.camera-preview');if(camera&&setting==='cam')camera.innerHTML=`<span>${icon(state.cam?'video':'videoOff')}</span><span>${state.cam?'Camera preview placeholder':'Your camera is off'}</span>`;toast('Preview setting updated. No device is accessed.');}
  });
  document.addEventListener('submit',e=>{
    const form=e.target;if(!form.id)return;e.preventDefault();if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));
    if(form.id==='signup-form'||form.id==='signin-form'){if(data.fullname){state.name=data.fullname.trim();save('name',state.name);}state.profile.email=data.email;save('profile',state.profile);go('event');toast(form.id==='signup-form'?'Sample account created. Register for the event when you enter.':'Signed into the sample account.');}
    else if(form.id==='chat-form'){state.messages.push(data.message.trim());if(state.messages[state.messages.length-1])setPanel('chat');else state.messages.pop();$('#chat-form input')?.focus();}
    else if(form.id==='question-form'){closeModal();toast('Your sample question was added to the session Q&A.');}
    else if(form.id==='booth-form'){state.booth={title:data.title,abstract:data.abstract,status:data.status,link:data.link};save('booth',state.booth);render();toast('Booth changes saved in this browser.');}
    else if(form.id==='profile-form'){state.name=data.name.trim();state.profile={...data,publicContacts:!!data.publicContacts,acceptRequests:!!data.acceptRequests};save('name',state.name);save('profile',state.profile);render();toast('Profile saved in this browser.');}
    else if(form.id==='create-event-form')saveEvent(true);
    else if(form.id==='invite-form'){closeModal();toast('Sample invitation prepared. No email was sent.');}
  });
  window.Connecta={state,chars,icon,toast,escape,render,actor,projects,pages,header,workspace,kpis,btn,action,iconButton,pill,status,poster,openModal,closeModal,setPanel,panelFrame,boothBody,download,save,read,go,extraViews:{}};
  window.addEventListener('hashchange',render);
  render();
})();
